    class GLContextHost {
        constructor(canvas) {
            this.canvas = canvas;
            this.gl = canvas.getContext('webgl2', { alpha: true, antialias: false, depth: false, premultipliedAlpha: true }) ||
                      canvas.getContext('webgl', { alpha: true, antialias: false, depth: false, premultipliedAlpha: true });
            if (!this.gl) throw new Error('WebGL not supported');
            this.isWebGL2 = this.gl instanceof WebGL2RenderingContext;
            this.gl.enable(this.gl.BLEND);
            this.gl.blendFunc(this.gl.ONE, this.gl.ONE_MINUS_SRC_ALPHA);
        }
        createShader(type, source) {
            const shader = this.gl.createShader(type);
            this.gl.shaderSource(shader, source);
            this.gl.compileShader(shader);
            if (!this.gl.getShaderParameter(shader, this.gl.COMPILE_STATUS)) {
                throw new Error(this.gl.getShaderInfoLog(shader));
            }
            return shader;
        }
        createProgram(vsSource, fsSource) {
            const vs = this.createShader(this.gl.VERTEX_SHADER, vsSource);
            const fs = this.createShader(this.gl.FRAGMENT_SHADER, fsSource);
            const prog = this.gl.createProgram();
            this.gl.attachShader(prog, vs);
            this.gl.attachShader(prog, fs);
            this.gl.linkProgram(prog);
            if (!this.gl.getProgramParameter(prog, this.gl.LINK_STATUS)) {
                throw new Error(this.gl.getProgramInfoLog(prog));
            }
            return prog;
        }
    }

